// ---------------------------------------------------------------------------
// 索引尾巴（打包后追加）：把每个特效的尺寸 / 时长 / 是否循环 / 是否有背景一次性算好，
// 为什么不在渲染器里现算：panel 一屏要摆 200 个格子，逐个去翻 208 个 meta 会让首屏明显卡一下；
// 而且 non-loop 特效必须知道 duration 才能「播完从头再来」。
(function () {
  var P = (typeof PixelFXAvatar !== 'undefined') ? PixelFXAvatar : (typeof window !== 'undefined' ? window.PixelFXAvatar : null);
  if (!P || !P.effects) return;
  var M = {}, ids = [];
  for (var id in P.effects) {
    var m = P.effects[id] && P.effects[id].meta;
    if (!m || !m.size) continue;                 // 没有尺寸的（转场以前的版本）直接跳过，画不出来
    var p = id.split('/');
    M[id] = {
      cat: p[0], name: p[1],
      size: [m.size[0], m.size[1]],
      origin: m.origin ? [m.origin[0], m.origin[1]] : [m.size[0] / 2, m.size[1] / 2],
      loop: !!m.loop,
      duration: m.duration > 0 ? m.duration : 1,
      bg: m.bg || null                            // 有 bg = 自带整幅背景（天气类），画的时候要裁满不要留边
    };
    ids.push(id);
  }
  P.meta = M;
  P.ids = ids;
  P.list = function () {
    var out = [];
    for (var i = 0; i < ids.length; i++) out.push({ id: ids[i], cat: M[ids[i]].cat, name: M[ids[i]].name });
    return out;
  };
})();
